\definecolor{housegrid}{HTML}{CCCCCC}
\draw[housegrid,line width=0.25pt,xstep=7mm,ystep=4mm] (0,0) grid (3,24);
\draw[black,->] (0,0)--(3.25,0);
\draw[black,->] (0,0)--(0,26);
\foreach \t in {0,1,2,3} {\draw[black] (\t,0)--(\t,-0.6);\node[below,font=\fontsize{8.5}{10}\selectfont] at (\t,-0.6) {$\t$};}
\foreach \d in {6,12,18,24} {\draw[black] (0,\d)--(-0.06,\d);\node[left,font=\fontsize{8.5}{10}\selectfont] at (-0.06,\d) {$\d$};}
